import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import { join } from "node:path";

const FULL_ALLOW = [
  "en*", "ar", "hy", "ca", "da", "nl", "fi", "fr", "fr-CA", "ga", "de", "el",
  "ht", "he", "hi", "hu", "is", "id", "it", "ja", "ko", "mi", "ms", "se",
  "nb", "nn", "fa", "pl", "pt", "pt-BR", "ru", "zh-Hans", "sl", "es", "sv",
  "th", "zh-Hant", "tr", "uk", "vi", "cy",
];

const demoDir = "/Users/dwahl/Scripts/pantoken/docs/demos";
const names = readdirSync(demoDir, { withFileTypes: true })
  .filter((e) => e.isDirectory())
  .map((e) => e.name);

let changedFiles = 0;
let changedKeys = 0;

for (const name of names) {
  const path = join(demoDir, name, "i18n.json");
  let raw;
  try {
    raw = readFileSync(path, "utf8");
  } catch {
    continue;
  }
  const data = JSON.parse(raw);
  let fileChanged = false;
  for (const [key, entry] of Object.entries(data)) {
    if (
      entry &&
      typeof entry === "object" &&
      entry.verbatim &&
      typeof entry.verbatim === "object" &&
      Array.isArray(entry.verbatim.allow) &&
      Object.keys(entry.verbatim).length === 1
    ) {
      const current = entry.verbatim.allow;
      const same =
        current.length === FULL_ALLOW.length &&
        current.every((v, i) => v === FULL_ALLOW[i]);
      if (!same) {
        entry.verbatim.allow = [...FULL_ALLOW];
        fileChanged = true;
        changedKeys++;
      }
    }
  }
  if (fileChanged) {
    writeFileSync(path, `${JSON.stringify(data, null, 2)}\n`);
    changedFiles++;
  }
}

console.log(`Updated ${changedKeys} key(s) across ${changedFiles} file(s).`);
EOF
